private func touch(_ url: URL) {
    guard FileManager.default.fileExists(atPath: url.path) else { return }
    try? FileManager.default.setAttributes([.modificationDate: Date()], ofItemAtPath: url.path)
}

/// 카드를 지운다. 돌고 있던 창을 닫고 작업 기록 폴더(`.myterm/jobs/<id>`)를 통째로 없앤다.
/// 이미 고쳐진 코드는 되돌리지 않는다.
func delete(_ job: JobSnapshot) {
    let prefix = "job-\(job.id.suffix(6))-"
    for session in [claude, codex] {
        for name in Tmux.windowNames(session: session.tmuxSession) where name.hasPrefix(prefix) {
            Tmux.killWindow(session: session.tmuxSession, name: name)
        }
    }
    do {
        try FileManager.default.removeItem(at: job.files.directory)
    } catch {
        lastError = "작업 기록을 지우지 못했어요: \(error.localizedDescription)"
        return
    }
    // Smart JIRA 수정 계획 카드였으면 받아 둔 첨부 · 링크(.smart-jira/<키>)도 지운다 — 같은 카드의 다른 작업이 남아 있으면 둔다
    if let key = SmartJira.jiraKey(job.meta.request),
       !jobs.contains(where: { $0.id != job.id && SmartJira.jiraKey($0.meta.request) == key }) {
        JiraMaterials.remove(workspace, key: key)
    }
    jobs.removeAll { $0.id == job.id }
    live[job.id] = nil
    if selectedJobId == job.id { selectedJobId = nil }
    lastError = nil
}

/// 카드를 종결로 닫는다 (커밋했거나, 커밋 없이 닫는 경우). 커밋하고 닫으면 Smart JIRA 가 완료로 옮긴다.
func close(_ job: JobSnapshot, committed: Bool = false) {
    FileManager.default.createFile(atPath: job.files.closed.path, contents: Data((committed ? #"{"committed":true}"# : "{}").utf8))
    refresh(job.id)
}

/// 설계 · 설계리뷰를 승인해서 작업을 시작한다.
/// 승인은 기다리던 회차의 요청 구간에만 남긴다 (다른 추가 요청의 승인으로 쓰이지 않게).
func approvePlan(_ job: JobSnapshot) {
    guard case .awaitingStart(let round) = job.phase else { return }
    do {
        try Data("{}".utf8).write(to: job.approvalURL(round), options: .atomic)
    } catch {
        lastError = "작업 시작 승인을 기록하지 못했어요: \(error.localizedDescription)"
        return
    }
    lastError = nil
    refresh(job.id)
    startLoopIfNeeded()
}

/// 합의가 안 될 때 사용자가 정한다 — 코드: 계속 수정 · 멈춤 / 설계: 한 번 더 논의(keepGoing) · 이대로 작업(proceed) · 멈춤
func decide(_ job: JobSnapshot, _ choice: GateDecision.Choice, comment: String? = nil) {
    let round: Int
    switch job.phase {
    case .awaitingDecision(let number), .awaitingConsensus(let number): round = number
    default: return
    }
    let comment = comment?.trimmingCharacters(in: .whitespacesAndNewlines)

private func startLoopIfNeeded() {
    guard loop == nil, isBusy else { return }
    loop = Task { [weak self] in
        while !Task.isCancelled {
            guard let self, self.isBusy else { break }
            self.tick()
            try? await Task.sleep(for: .seconds(1))
        }
        self?.loop = nil
    }
}

private func tick() {
    for job in jobs where !job.isFinished {
        advance(job)
        refresh(job.id)
    }
    for job in jobs { updateLive(job) }
}

/// 돌고 있는 단계의 tmux 창에서 지금 찍히고 있는 마지막 몇 줄을 읽어 둔다.
/// (Claude · Codex 칸은 한 번에 한 작업의 창만 보여 주므로, 카드에서도 지금 하는 일을 볼 수 있게 한다.)
private func updateLive(_ job: JobSnapshot) {
    guard let (step, round) = job.activeStep else {
        live[job.id] = nil
        return
    }
    let session = session(job.agent(step, round))
    guard let text = Tmux.output(["capture-pane", "-p", "-J", "-t", "=\(session.tmuxSession):=\(windowName(job, step, round))"]) else { return }
    let lines = text.split(separator: "\n")
        .map { $0.trimmingCharacters(in: .whitespaces) }
        .filter { !$0.isEmpty }
    let since = (try? job.files.started(step, round).resourceValues(forKeys: [.contentModificationDateKey]))?.contentModificationDate
    live[job.id] = Live(lines: Array(lines.suffix(6)), since: since)
}

private func advance(_ job: JobSnapshot) {
    guard let (step, round) = job.activeStep else { return }
    if FileManager.default.fileExists(atPath: job.files.started(step, round).path) {
        checkAlive(job, step, round)
    } else {
        start(job, step, round)
    }
}

// MARK: - Steps

func followUp(_ job: JobSnapshot, _ instruction: String) {
    let instruction = instruction.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !instruction.isEmpty else { return }
    let last = job.rounds.last?.number ?? 0
    let next = last + 1
    // 받기 전 상태로 가른다: 지금 구간에서 작업을 시작한 적 있으면 새 추가 요청 — 지금의 추가 요청 배치를 확정한다.
    // 작업 전(설계 · 설계리뷰 실패, 되물음, 합의 멈춤)이면 같은 요청의 보완 — 기존 배치 · 지시를 이어 간다.
    let newPlacement = last > 0 && job.segmentWorkStarted(last)
    do {
        if newPlacement {
            try JobJSON.save(settings.processSnapshot(.followUp), to: job.files.placement(next))
        }
        try instruction.write(to: job.files.followUp(next), atomically: true, encoding: .utf8)
